'use strict';

/**
* Compute the modified Bessel function of the second kind of order one.
*
* @module @stdlib/math/base/special/besselk1
*
* @example
* var k1 = require( '@stdlib/math/base/special/besselk1' );
*
* var v = k1( 0.0 );
* // returns Infinity
*
* v = k1( 1.0 );
* // returns ~0.6019
*
* v = k1( 5.0 );
* // returns ~0.004045
*
* v = k1( -1.0 );
* // returns NaN
*
* v = k1( Infinity );
* // returns 0.0
*
* v = k1( NaN );
* // returns NaN
*/

// MODULES //

var k1 = require( './main.js' );


// EXPORTS //

module.exports = k1;
